function alertRows(){const A=computeAll();return A.all.map(a=>({id:a.id,a,sev:a.sev,sevn:SEVN[a.sev][0],msg:a.msg,ci:ciName(a.ci),svcn:SVN(a.svc),rulen:(rOf(a.rule)||{n:a.rule==="EXT"?"Event feed":a.rule}).n,count:a.count,from:a.from,to:a.to,state:a.state||(a.active?"Open":"Cleared"),grp:a.grp||"",src:a.src}))}
