/* ---------- topology mini map ---------- */
function topoSVG(cis,rc,o){o=o||{};const set=new Set(cis);const W=o.w||640,nh=30,nw=176,gap=18;const lay={};const ed=CIEDGE.filter(e=>set.has(e[0])&&set.has(e[1]));
 const depth={};const q=[rc];depth[rc]=0;while(q.length){const x=q.shift();ed.forEach(e=>{if(e[1]===x&&depth[e[0]]==null){depth[e[0]]=depth[x]+1;q.push(e[0])}})}
 cis.forEach(c=>{if(depth[c]==null)depth[c]=0});const levels={};cis.forEach(c=>{(levels[depth[c]]=levels[depth[c]]||[]).push(c)});const L=Object.keys(levels).map(Number).sort((a,b)=>b-a);const Hh=L.length*(nh+gap+10)+10;let g="",pos={};
 L.forEach((lv,i)=>{const row=levels[lv],tot=row.length*(nw+gap)-gap,x0=(W-tot)/2;row.forEach((c,j)=>{pos[c]={x:x0+j*(nw+gap),y:8+i*(nh+gap+10)}})});
 ed.forEach(e=>{const a=pos[e[0]],b=pos[e[1]];if(!a||!b)return;g+=`<path d="M${a.x+nw/2} ${a.y+nh}C${a.x+nw/2} ${a.y+nh+14} ${b.x+nw/2} ${b.y-14} ${b.x+nw/2} ${b.y}" fill="none" stroke="var(--line-art)" stroke-width="2" marker-end="url(#obsAr)"><title>${H(ciName(e[0])+" "+e[2]+" "+ciName(e[1]))}</title></path>`});
 cis.forEach(c=>{const p=pos[c],st=ciStatus(c);g+=`<g class="obs-tn2" data-obs-ci="${H(c)}" tabindex="0" role="button" aria-label="${H(ciName(c))}"><rect x="${p.x}" y="${p.y}" width="${nw}" height="${nh}" rx="9" fill="var(--glass2)" stroke="var(${STC[st][1]})" stroke-width="${c===rc?3:1.6}"/><circle cx="${p.x+14}" cy="${p.y+nh/2}" r="5" fill="var(${STC[st][1]})"/><text x="${p.x+26}" y="${p.y+nh/2+4}" font-size="12" fill="var(--ink)">${H(ciName(c).slice(0,22))}</text>${c===rc?`<text x="${p.x+nw-8}" y="${p.y+nh/2+4}" font-size="10" text-anchor="end" fill="var(--bad-f)" font-weight="700">ROOT</text>`:""}</g>`});
 return `<div class="obs-heat"><svg viewBox="0 0 ${W} ${Hh}" role="img" aria-label="Dependency map of the correlated CIs. Arrows point from a CI to what it depends on." style="min-width:${Math.min(W,460)}px"><defs><marker id="obsAr" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--line-art)"/></marker></defs>${g}</svg></div>`}

