function sgCard(s){const r=rOf(s.rule);return `<article class="obs-sg"><div class="row sp"><span class="row"><span class="pill ${s.conf>=.85?"good":s.conf>=.7?"info":"warn"}">Confidence ${Math.round(s.conf*100)}%</span><span class="pill mute">${s.type==="window"?"Suppression window":s.type==="hyst"?"Hysteresis":"Threshold"}</span></span>${aiChip({model:"Event Correlator",conf:s.conf,title:"Suppression suggestion",note:"Based on seven days of alerts, your false positive marks and how regular the timing is."})}</div><h4>${H(s.title)}</h4><p class="muted small">${H(s.why)}</p><div class="row obs-pv"><span class="stat"><small>Alerts in 7 days now</small><span class="num">${s.before}</span></span><span class="stat"><small>With this change</small><span class="num">${s.after}</span></span><span class="stat"><small>Removed</small><span class="num">${s.before?Math.round((1-s.after/s.before)*100):0}%</span></span></div><div class="row"><button class="btn primary" data-obs-sgok="${H(s.id)}">Accept</button><button class="btn" data-obs-sgno="${H(s.id)}">Reject</button>${r?`<button class="btn quiet" data-obs-lab="${r.id}">Open in threshold lab</button>`:""}</div></article>`}
