 <div class="tscroll"><table><thead><tr><th>CI</th><th>Current</th><th>Proposed</th><th>Change</th></tr></thead><tbody>${rows.filter(r=>r.a.length||r.b.length).map(r=>`<tr><td>${H(r.c.name)}</td><td class="num">${r.a.length}</td><td class="num">${r.b.length}</td><td class="num">${r.b.length-r.a.length>0?"+":""}${r.b.length-r.a.length}</td></tr>`).join("")||`<tr><td colspan="4" class="muted">No CI of this class alerted in 7 days under either setting.</td></tr>`}</tbody></table></div>
