function covCalc(){let f=0,n=0;const cats=COV.map(c=>{const it=c[3].map(x=>({n:x[0],s:(O.cov&&O.cov[x[0]])||x[1],note:x[2],base:x[1]}));const sc=sum(it,x=>x.s==="full"?1:x.s==="partial"?.5:x.s==="accepted"?1:0);f+=sc;n+=it.length;return {id:c[0],n:c[1],tools:c[2],it,pct:Math.round(sc/it.length*100)}});return {cats,pct:Math.round(f/n*100),gaps:cats.flatMap(c=>c.it.filter(x=>x.s==="gap"||x.s==="partial").map(x=>Object.assign({cat:c.n},x)))}}
