/* ---------- dashboards: builder with drag and drop ---------- */
function defDash(){return [
 {id:"d1",n:"NOC overview",tiles:[{id:"t1",type:"alerts",title:"Open alerts",w:1},{id:"t2",type:"funnel",title:"Noise funnel",w:1},{id:"t3",type:"status",svc:"svc_portal",title:"Standards Portal",w:1},{id:"t4",type:"status",svc:"svc_search",title:"Search and indexing",w:1},{id:"t5",type:"line",m:"lat",cis:["ci_por4","ci_cod4","ci_sea2"],rg:"24h",title:"Application latency p95",w:2},{id:"t6",type:"top",m:"cpu",title:"Hottest CPUs",w:1},{id:"t7",type:"slo",slo:"SL1",title:"Portal availability SLO",w:1}]},
 {id:"d2",n:"Portal service health",tiles:[{id:"t1",type:"stat",m:"lat",ci:"ci_por4",title:"Portal p95",w:1},{id:"t2",type:"stat",m:"err",ci:"ci_por4",title:"Portal error rate",w:1},{id:"t3",type:"gauge",m:"cpu",ci:"ci_cod2",title:"Database CPU",w:1},{id:"t4",type:"line",m:"cpu",cis:["ci_cod0","ci_cod1","ci_cod2"],rg:"6h",title:"CPU: app servers and database",w:2},{id:"t5",type:"line",m:"err",cis:["ci_por4","ci_cod3"],rg:"24h",title:"Errors",w:2}]},
 {id:"d3",n:"Search and indexing",tiles:[{id:"t1",type:"stat",m:"queue",ci:"ci_sea0",title:"Indexer 1 queue",w:1},{id:"t2",type:"stat",m:"queue",ci:"ci_sea1",title:"Indexer 2 queue",w:1},{id:"t3",type:"line",m:"queue",cis:["ci_sea0","ci_sea1"],rg:"6h",title:"Queue depth",w:2},{id:"t4",type:"slo",slo:"SL4",title:"Index freshness SLO",w:1}]}]}
O.dashes=O.dashes||defDash();
const tcl=t=>({line:"Line chart",stat:"Number with trend",gauge:"Gauge",status:"Service status",top:"Top CIs",alerts:"Alert counts",slo:"SLO",funnel:"Noise funnel"})[t]||t;
function tileBody(t){const A=computeAll();
 if(t.type==="line"){const ss=(t.cis||[]).filter(c=>ciOf(c)).map(c=>{const s=ser(c,t.m,t.rg||"24h");return {l:ciName(c),v:s.v,t0:s.t0,step:s.step}});return ss.length?tsChart({series:ss,fmt:MET[t.m].fmt,w:560,h:210,sw:1.8,min:t.m==="avail"?90:0,max:t.m==="avail"?100.5:undefined,label:t.title})+(ss.length>1?legendSeries(ss):""):empty("No data")}
 if(t.type==="stat"){const s=ser(t.ci,t.m,"6h"),v=s.v[s.v.length-1],r=O.rules.find(x=>x.on&&x.m===t.m&&x.kind==="static"),bad=r&&(r.op==="<"?v<r.crit:v>r.crit),w=r&&(r.op==="<"?v<r.warn:v>r.warn);return `<div class="obs-big"><span class="num" data-role="metric" style="color:var(${bad?"--bad-f":w?"--warn-f":"--ink"})">${MET[t.m].fmt(v)}</span><small class="muted">${H(ciName(t.ci))} · ${MET[t.m].n}</small>${spark(s.v,230,40,col(bad?"--bad-f":w?"--warn-f":MET[t.m].col))}</div>`}
 if(t.type==="gauge"){const v=lastv(t.ci,t.m),r=O.rules.find(x=>x.on&&x.m===t.m&&x.kind==="static");const c=r&&v>r.crit?"--bad-f":r&&v>r.warn?"--warn-f":"--good-f";return `<div class="obs-gg">${ring(v,MET[t.m].max,130,col(c),MET[t.m].fmt(v),20)}<small class="muted">${H(ciName(t.ci))}</small></div>`}
 if(t.type==="status"){const st=svcState(t.svc),al=A.day.filter(a=>a.svc===t.svc&&a.active&&!a.sup&&!a.fp).length;return `<button class="obs-tile st-${st}" data-obs-svc="${t.svc}"><span class="row sp"><b>${H(SVN(t.svc))}</b>${stDot(st)}</span><span class="obs-tn"><span class="num" data-role="metric">${al}</span><small>open alerts</small></span><span class="muted small">${STC[st][0]}</span></button>`}
 if(t.type==="top"){const top=CIREG.filter(c=>metsOf(c).includes(t.m)).map(c=>({c,v:lastv(c.id,t.m)})).sort((a,b)=>b.v-a.v).slice(0,6);return barsH(top.map(x=>({l:`<button class="obs-lk" data-obs-ci="${x.c.id}">${H(x.c.name)}</button>`,v:x.v,t:MET[t.m].fmt(x.v),c:MET[t.m].col})))}
 if(t.type==="alerts"){const op=A.day.filter(a=>a.active&&!a.sup&&!a.fp);return `<div class="statrow" style="margin:0">${[[1,2],[3],[4]].map((g,i)=>stat(["Sev 1 and 2","Sev 3","Sev 4"][i],op.filter(a=>g.includes(a.sev)).length,"open",i===0&&op.some(a=>a.sev<=2)?"crit":"")).join("")}</div>`}
 if(t.type==="slo"){const s=O.slos.find(x=>x.id===t.slo)||O.slos[0],k=sloCalc(s),st=sloSt(s);return `<div class="obs-gg">${ring(Math.max(0,k.left),100,120,col(st==="good"?"--good-f":st==="warn"?"--warn-f":"--bad-f"),Math.max(0,Math.round(k.left))+"%",20)}<small class="muted">${H(s.n)}<br>SLI ${P2(k.sli)}%</small></div>`}
 if(t.type==="funnel"){return barsH(["Raw events","Unique alerts","After suppression","Groups","Actionable","Incidents"].map((l,i)=>({l,v:Math.log10(Math.max(2,A.fun[i])),t:N0(A.fun[i]),c:"--p4"})))}
 return ""}
function dashHTML(d,edit){return `<div class="obs-tg ${edit?"edit":""}" data-dnd="dash_${d.id}" data-dnd-scope="obs_tile">${d.tiles.map(t=>`<section class="card glass obs-t w${t.w}" data-dnd-id="${t.id}" tabindex="0">${edit?`<div class="obs-th"><span class="row">${grip}<b>${H(t.title)}</b></span><span class="row"><button class="btn quiet" data-obs-tilew="${d.id}:${t.id}" aria-label="Change width">${t.w===2?"Narrow":"Wide"}</button><button class="btn quiet" data-obs-tiledel="${d.id}:${t.id}" aria-label="Remove tile ${H(t.title)}">Remove</button></span></div>`:`<div class="obs-th"><b>${H(t.title)}</b><span class="muted small">${tcl(t.type)}</span></div>`}${tileBody(t)}</section>`).join("")||empty("No tiles yet","Add a chart, number, gauge or status tile.")}</div>`}
function dashPane(){const d=O.dashes.find(x=>x.id===O.dashSel)||O.dashes[0];
 return `<div class="statrow">${stat("Dashboards",O.dashes.length,"yours and shared")}${stat("Tiles on this dashboard",d.tiles.length,"drag to rearrange in edit mode")}${stat("Tile types",8,"line, number, gauge, status, top list, alerts, SLO, funnel")}</div>
 ${card("Dashboards","Build views like Grafana or SolarWinds dashboards from any metric. Choose Edit, drag tiles into the order you want, add tiles from any metric, then Save.",`<div class="row obs-ctl2"><div class="fchips" role="radiogroup" aria-label="Dashboard">${O.dashes.map(x=>`<button class="chip" data-obs-dsel="${x.id}" aria-pressed="${x.id===d.id}">${H(x.n)}</button>`).join("")}</div><button class="btn quiet" data-obs-newdash>New dashboard</button></div>
 <div class="row obs-act">${O.edit?`<button class="btn primary" data-obs-dsave>Save dashboard</button><button class="btn" data-obs-dcancel>Cancel</button><button class="btn" data-obs-addtile="">Add tile</button>`:`<button class="btn primary" data-obs-dedit>Edit</button><button class="btn" data-obs-ddup="${d.id}">Duplicate</button><button class="btn quiet" data-obs-ddel="${d.id}">Delete</button>`}</div>${dashHTML(d,O.edit)}`)}`}
function tileForm(pre){pre=pre||{};const [pci,pm]=String(pre).split(":");openForm({id:"obs_tile",title:"Add a tile",story:"Choose what to show. Line charts compare up to three CIs. Number and gauge tiles show one CI and turn amber or red when a threshold is crossed. You can drag the tile into place afterwards.",submit:"Add tile",
 fields:[{k:"dash",label:"Dashboard",type:"select",opts:O.dashes.map(d=>[d.id,d.n])},{k:"type",label:"Tile type",type:"chips",opts:Object.keys({line:1,stat:1,gauge:1,status:1,top:1,alerts:1,slo:1,funnel:1}).map(k=>[k,tcl(k)])},{k:"m",label:"Metric",type:"select",opts:Object.keys(MET).map(k=>[k,MET[k].n]),show:v=>["line","stat","gauge","top"].includes(v.type)},{k:"ci",label:"Configuration item",type:"select",opts:CIREG.map(c=>[c.id,c.name+" ("+c.class+")"]),show:v=>["line","stat","gauge"].includes(v.type)},{k:"svc",label:"Service",type:"select",opts:SVCREG.map(s=>[s.id,s.n]),show:v=>v.type==="status"},{k:"slo",label:"SLO",type:"select",opts:O.slos.map(s=>[s.id,s.n]),show:v=>v.type==="slo"},{k:"rg",label:"Range",type:"chips",opts:Object.keys(RANGES),show:v=>v.type==="line"},{k:"title",label:"Title",type:"text",ph:"Leave blank to name it automatically"},{k:"w",label:"Width",type:"chips",opts:[["1","Normal"],["2","Wide"]]}],
 defaults:{dash:O.dashSel,type:"line",m:pm&&MET[pm]?pm:"cpu",ci:pci||"ci_cod2",svc:"svc_portal",slo:"SL1",rg:"24h",w:"1"},
 onSubmit:v=>{const d=O.dashes.find(x=>x.id===v.dash)||O.dashes[0];const t={id:"t"+(d.tiles.length+1+Math.floor(Math.random()*90)),type:v.type,m:v.m,ci:v.ci,cis:[v.ci],svc:v.svc,slo:v.slo,rg:v.rg||"24h",w:+v.w||1,title:v.title||(v.type==="status"?SVN(v.svc):v.type==="slo"?"SLO":MET[v.m]?MET[v.m].n+(v.ci?" · "+ciName(v.ci):""):tcl(v.type))};d.tiles.push(t);O.dashSel=d.id;audit("added dashboard tile",d.n+": "+t.title);render();return {toast:"Tile added to "+d.n,audit:t.title}}})}
function dashForm(){openForm({id:"obs_dash",title:"New dashboard",story:"Starts empty, or from one of the ready-made layouts. Add tiles from any metric afterwards.",submit:"Create dashboard",fields:[{k:"n",label:"Name",type:"text",req:true,ph:"For example: Finance systems"},{k:"from",label:"Start from",type:"chips",opts:[["blank","Blank"],["noc","NOC overview"],["svc","Service health"]]}],defaults:{from:"blank"},onSubmit:v=>{const id="d"+(O.dashes.length+1+Math.floor(Math.random()*50)),base=v.from==="noc"?O.dashes[0]:v.from==="svc"?O.dashes[1]:null;O.dashes.push({id,n:v.n,tiles:base?JSON.parse(JSON.stringify(base.tiles)):[]});O.dashSel=id;O.edit=true;O.dsnap=JSON.stringify(O.dashes);audit("created dashboard",v.n);render();return {toast:"Dashboard created. Add tiles and drag them into place.",audit:v.n}}})}
DND.on("obs_tile",(id,from,to,idx)=>{const d=O.dashes.find(x=>"dash_"+x.id===from);if(!d)return;const i=d.tiles.findIndex(t=>t.id===id);if(i<0)return;const [t]=d.tiles.splice(i,1);d.tiles.splice(Math.min(idx>i?idx-1:idx,d.tiles.length),0,t);audit("moved dashboard tile",d.n+": "+t.title);toast("Moved "+t.title,"good");render()});
DND.on("obs_step",(id,from,to,idx)=>{const el=document.querySelector('[data-dnd="steps"]'),sc=scOf(el&&el.dataset.sc);if(!sc)return;const i=+id;draft(sc);const [t]=sc.steps.splice(i,1);sc.steps.splice(Math.min(idx>i?idx-1:idx,sc.steps.length),0,t);audit("reordered runbook steps",sc.id);toast("Step moved. Publish a new version to keep it.","good");render()});

