/* ---------- network map ---------- */
const NETN=[["isp1","ISP A (primary)","WAN",90,50],["isp2","ISP B (backup)","WAN",90,180],["fw","Edge firewall pair","Firewall",270,115,"ci_fw"],["vpn","VPN gateway","VPN",270,250,"ci_vpn"],["core","Core switch, Norwalk","Switch",450,115],["d1","Distribution A","Switch",640,50],["d2","Distribution B","Switch",640,180],["wifi","Wi-Fi controller","Wi-Fi",830,50],["ap","Access points (42)","Wi-Fi",830,150],["dc","Washington office router","Router",450,250],["az","Azure East US 2 hub","Cloud",450,370,"ci_az"],["dns","Azure DNS","Cloud",270,370,"ci_dns"],["waf","Portal WAF and Front Door","Cloud",640,370,"ci_por3"],["usr","Remote editors (140)","Users",90,310]].map(x=>({id:x[0],n:x[1],t:x[2],x:x[3],y:x[4],ci:x[5]}));
const NETL=[["isp1","fw","ISP A",1000,"ci_fw"],["isp2","fw","ISP B standby",500,null],["fw","core","Core uplink",10000,"ci_fw"],["fw","vpn","VPN trunk",1000,"ci_vpn"],["vpn","usr","VPN tunnels",1000,"ci_vpn"],["core","d1","Uplink A",10000,null],["core","d2","Uplink B",10000,null],["d1","wifi","Wi-Fi uplink",1000,null],["d1","ap","AP trunk",1000,null],["core","dc","MPLS to Washington",100,null],["fw","az","ExpressRoute",1000,"ci_fw"],["az","dns","DNS",1000,null],["az","waf","Front Door peering",1000,null],["core","az","Private link",1000,null]];
function linkSt(l){const ci=l[4];let u=ci?val(ci,"util",NOW_T):6+hn(l[2],3)*38,loss=ci?val(ci,"loss",NOW_T):hn(l[2],4)*.04,av=ci&&metsOf(ciOf(ci)||{}).includes("avail")?val(ci,"avail",NOW_T):100;if(l[2]==="ISP B standby"){u=2;}const fl=ci==="ci_vpn"&&av<99.5||false;const s=loss>=2||u>=90||av<98?"crit":loss>=.5||u>=75?"warn":"ok";return {u,loss,av,s:fl&&s==="ok"?"warn":s,flap:ci==="ci_vpn"&&(NOW_T>=640&&NOW_T<=790)}}
function netMap(){const A=computeAll();const pos={};NETN.forEach(n=>pos[n.id]=n);let g="";
 NETL.forEach((l,i)=>{const a=pos[l[0]],b=pos[l[1]],st=linkSt(l),c=st.s==="crit"?"--bad-f":st.s==="warn"?"--warn-f":"--good-f";g+=`<g class="obs-lnk ${st.flap?"flap":""}"><line x1="${a.x+75}" y1="${a.y+17}" x2="${b.x+75}" y2="${b.y+17}" stroke="var(${c})" stroke-width="${2+Math.min(6,l[3]/2500)}" stroke-linecap="round" ${st.flap?'stroke-dasharray="7 6"':""} opacity=".85"><title>${H(l[2]+": "+P1(st.u)+"% utilized, loss "+P2(st.loss)+"%, "+(l[3]>=1000?l[3]/1000+" Gbps":l[3]+" Mbps"))}</title></line><text class="ax" x="${(a.x+b.x)/2+75}" y="${(a.y+b.y)/2+13}" text-anchor="middle" paint-order="stroke" stroke="var(--bg)" stroke-width="3">${Math.round(st.u)}%</text></g>`});
 NETN.forEach(n=>{const st=n.ci?ciStatus(n.ci):(n.t==="Users"?(ciStatus("ci_vpn")==="ok"?"ok":"warn"):"ok");g+=`<g class="obs-nd" ${n.ci?`data-obs-ci="${n.ci}"`:`data-obs-nd="${n.id}"`} tabindex="0" role="button" aria-label="${H(n.n)}: ${STC[st][0]}"><rect x="${n.x}" y="${n.y}" width="150" height="34" rx="10" fill="var(--glass2)" stroke="var(${STC[st][1]})" stroke-width="2.2"/><circle cx="${n.x+14}" cy="${n.y+17}" r="5.5" fill="var(${STC[st][1]})"/><text x="${n.x+26}" y="${n.y+21}" font-size="12" fill="var(--ink)">${H(n.n.slice(0,22))}</text></g>`});
 return `<div class="obs-heat"><svg viewBox="0 0 980 430" role="group" aria-label="Network map: devices and links colored by status" style="min-width:760px">${g}</svg></div>`+legend([["Link or device OK","--good-f"],["Warning: over 75% utilized or loss over 0.5%","--warn-f"],["Critical: over 90%, loss over 2% or tunnel availability under 98%","--bad-f"]])+`<p class="muted small">Line thickness shows capacity. A dashed line is flapping. Numbers on links are utilization.</p>`}
function siteMap(){const sites=[["Norwalk HQ",420],["Washington",96],["Chicago",64],["Austin",58],["Seattle",52],["Phoenix",44],["Prague",30],["Azure East US 2",610],["Azure West US 2",300],["Azure West Europe",180],["Branch offices (12)",240],["Remote and VPN",120]];const W=760,Hh=330,cx=W/2,cy=Hh/2;let g="";sites.forEach((s,i)=>{const a=i/sites.length*Math.PI*2-Math.PI/2,x=cx+Math.cos(a)*270,y=cy+Math.sin(a)*125,r=hn(s[0],4);const crit=Math.round(s[1]*(i===7?.012:i===3?.008:.002)),warn=Math.round(s[1]*(.02+r*.03)),c=crit?"--bad-f":warn>s[1]*.04?"--warn-f":"--good-f";g+=`<line x1="${cx}" y1="${cy}" x2="${x}" y2="${y}" stroke="var(--line-art)" stroke-width="2"/><g class="obs-nd" data-obs-hostf="Network device" tabindex="0" role="button" aria-label="${H(s[0])}"><rect x="${x-62}" y="${y-22}" width="124" height="44" rx="12" fill="var(--glass2)" stroke="var(${c})" stroke-width="2.4"/><text x="${x}" y="${y-4}" text-anchor="middle" font-size="12" fill="var(--ink)" font-weight="600">${H(s[0])}</text><text x="${x}" y="${y+12}" text-anchor="middle" font-size="11" fill="var(--muted)">${s[1]} devices · ${crit} crit · ${warn} warn</text></g>`});
 g+=`<circle cx="${cx}" cy="${cy}" r="34" fill="var(--glass2)" stroke="var(--accent)" stroke-width="2"/><text x="${cx}" y="${cy+4}" text-anchor="middle" font-size="12" fill="var(--ink)" font-weight="700">Core</text>`;return `<div class="obs-heat"><svg viewBox="0 0 ${W} ${Hh}" role="group" aria-label="Sites, aggregated" style="min-width:640px">${g}</svg></div><p class="muted small">At enterprise volume the map shows sites with device counts and worst status instead of every device. Select a site to filter the host list to network devices. The detailed map appears when you filter to one site.</p>`}
function netPane(){const L=NETL.map(l=>Object.assign({l},linkSt(l)));const bad=L.filter(x=>x.s!=="ok"),fl=L.filter(x=>x.flap).length;const top=L.slice().sort((a,b)=>b.u-a.u).slice(0,5);
 return `<div class="statrow">${stat("Links",L.length,N0(NETN.length)+" devices on the detail map")}${stat("Links with a problem",bad.length,bad.map(x=>x.l[2]).join(", ")||"none",bad.length?"crit":"")}${stat("Flapping links",fl,fl?"VPN tunnels":"none")}${stat("Busiest link",P1(top[0].u)+"%",top[0].l[2])}</div>
 ${card("Network map","Devices and links drawn from the CMDB and the network scan. Link color is the worst of utilization, packet loss and tunnel availability. Select a device to open its host page.",SCALE.on?siteMap():netMap())}
 ${card("Busiest links","Utilization now.",barsH(top.map(x=>({l:H(x.l[2]),v:x.u,t:P1(x.u)+"%",c:x.s==="ok"?"--p4":x.s==="warn"?"--warn-f":"--bad-f"}))))}`}

/* ---------- logs and traces ---------- */
const LOGP=[["ERROR","Timeout expired waiting for a connection from the pool (codif-sql-prd)","svc_cod","ci_cod2","err",548,4812],["WARN","Slow query {ms} ms: SELECT … FROM paragraphs WHERE standard_id = @p0","svc_cod","ci_cod2","lat",548,1204],["ERROR","indexer: checkpoint write failed, retrying (PRB0007)","svc_search","ci_sea0","queue",545,188],["WARN","queue depth {n} exceeds 5000","svc_search","ci_sea0","queue",560,640],["ERROR","502 Bad Gateway from upstream taxonomy-api","svc_int","ci_int0","err",null,97],["WARN","CA-007: legacy authentication blocked for {user}","svc_id","ci_ca","",680,212],["ERROR","TLS handshake failed for client {ip}","svc_portal","ci_por3","err",552,33],["WARN","backup job warning: retry {n} of 3","svc_cr","ci_cr2","err",null,14],["ERROR","Journal post rejected: period already locked","svc_erp","ci_erp2","",null,41],["ERROR","NullReferenceException in EditorSession.Save()","svc_cod","ci_cod4","err",553,7,1],["INFO","publish job {id} completed in {s} s","svc_cod","ci_cod4","",null,2031],["INFO","health probe ok","svc_portal","ci_por0","",null,12402]];
function logHour(p,k){const base=p[6]/24,t=NOW_T-(23-k)*60,sp=p[5]!=null&&t>=p[5]?1+Math.min(4,(t-p[5])/90):.45+hn(p[1],k)*.5;let v=base*(p[5]==null?.6+hn(p[1],k+40)*.8:(p[5]!=null&&t>=p[5]?sp*3:.18));if(p[7]&&t<p[5])v=0;return Math.round(Math.max(0,v))}
function logRows(){const q=(O.logQ||"").toLowerCase();return LOGP.map((p,i)=>{const h=[...Array(24)].map((_,k)=>logHour(p,k)),tot=sum(h);return {id:"LP"+(i+1),lvl:p[0],pat:p[1],svc:p[2],ci:p[3],h,tot,isNew:!!p[7],trend:h.slice(-3).reduce((a,b)=>a+b,0)/Math.max(1,h.slice(0,12).reduce((a,b)=>a+b,0)/4)}}).filter(r=>!q||r.pat.toLowerCase().includes(q)||SVN(r.svc).toLowerCase().includes(q)||r.lvl.toLowerCase()===q)}
const LVC={ERROR:"bad",WARN:"warn",INFO:"info"};
const TRACES=[{id:"7f3a91c2e04b",op:"GET /standards/ISO-9001/clause/4",dur:6840,err:false,story:"Slow request during the 09:08 incident. 4.83 s of the 6.84 s is one database query waiting for a connection.",sp:[["portal-web: GET /standards/…","svc_portal",0,6840,0],["standards-platform: GET /api/clause","svc_cod",40,6740,1],["entra-id: validate token","svc_id",60,70,2],["codif-sql-prd: SELECT paragraphs","svc_cod",150,4830,2,1],["search-api: GET /related","svc_search",5000,1100,2],["render clause view","svc_portal",6100,700,1]]},{id:"b21d5e870a39",op:"GET /standards/ISO-9001/clause/4",dur:420,err:false,story:"The same request before the incident, for comparison.",sp:[["portal-web: GET /standards/…","svc_portal",0,420,0],["standards-platform: GET /api/clause","svc_cod",12,330,1],["entra-id: validate token","svc_id",14,18,2],["codif-sql-prd: SELECT paragraphs","svc_cod",40,120,2],["search-api: GET /related","svc_search",170,140,2],["render clause view","svc_portal",330,85,1]]},{id:"c9e4400f7d12",op:"POST /editor/draft/save",dur:30002,err:true,story:"Editors could not save: the save call hit the 30 second timeout (INC0413).",sp:[["standards-platform: POST /draft/save","svc_cod",0,30002,0,1],["entra-id: validate token","svc_id",10,60,1],["codif-sql-prd: UPDATE drafts","svc_cod",90,29900,1,1]]},{id:"4d0be77a1c58",op:"GET /v1/taxonomy/terms (01:12)",dur:15030,err:true,story:"The nightly batch makes the gateway return 502 for about 15 minutes (PRB0008).",sp:[["apim-gateway: GET /v1/taxonomy/terms","svc_int",0,15030,0,1],["taxonomy-api: GET terms","svc_data",25,15000,1,1]]}];
function waterfall(t){const W=760,rh=30,L=250,T=24,Hh=T+t.sp.length*rh+26,sx=ms=>L+(W-L-16)*ms/t.dur;let g="";for(let i=0;i<=4;i++){const x=sx(t.dur*i/4);g+=`<line class="gridl" x1="${x}" x2="${x}" y1="${T-6}" y2="${Hh-20}"/><text class="ax" x="${x}" y="${Hh-6}" text-anchor="middle">${t.dur>=1000?P1(t.dur*i/4000)+" s":Math.round(t.dur*i/4)+" ms"}</text>`}
 const cl=["--p4","--u3","--w1","--e4","--s3","--p1","--p2"];const sv=[...new Set(t.sp.map(s=>s[1]))];t.sp.forEach((s,i)=>{const y=T+i*rh,c=cl[sv.indexOf(s[1])%7];g+=`<text x="${8+s[4]*14}" y="${y+18}" font-size="12" fill="var(--ink)">${H(s[0].slice(0,34-s[4]*2))}</text><rect x="${sx(s[2])}" y="${y+5}" width="${Math.max(3,sx(s[2]+s[3])-sx(s[2]))}" height="18" rx="5" fill="var(${s[5]?"--bad-f":c})" opacity="${s[5]?.95:.8}"><title>${H(s[0]+": "+s[3]+" ms from "+s[2]+" ms")}</title></rect><text x="${Math.min(W-6,sx(s[2]+s[3])+6)}" y="${y+18}" font-size="11" fill="var(--muted)" ${sx(s[2]+s[3])>W-70?'text-anchor="end"':""}>${s[3]>=1000?P1(s[3]/1000)+" s":s[3]+" ms"}</text>`});
 return `<div class="obs-heat"><svg viewBox="0 0 ${W} ${Hh}" role="img" aria-label="Trace waterfall: each bar is one operation" style="min-width:620px">${g}</svg></div>`}
function logsPane(){const rows=logRows(),errs=rows.filter(r=>r.lvl==="ERROR"),tr=TRACES.find(t=>t.id===O.traceSel)||TRACES[0],cl=[{n:"Database connection pool exhausted",pat:[0,1],g:"G1",txt:"The Standards Platform waits for database connections; slow queries and timeouts follow."},{n:"Search indexing backlog",pat:[2,3],g:"G2",txt:"The indexer cannot write checkpoints, so the queue grows."},{n:"Nightly batch gateway errors",pat:[4],g:null,txt:"Every night around 01:00 the taxonomy gateway returns 502."}];
 const T=btHTML({id:"obs_log",h:380,rowH:56,key:"id",facets:["lvl","svc"],sort:{k:"tot",d:-1},cols:[{k:"lvl",label:"Level",val:r=>r.lvl,fmt:r=>`<span class="pill ${LVC[r.lvl]}">${r.lvl}</span>`},{k:"pat",label:"Pattern",wrap:1,val:r=>r.pat,fmt:r=>`<span class="obs-mono">${H(r.pat)}</span>${r.isNew?` <span class="pill info">New today</span>`:""}`},{k:"svc",label:"Service",val:r=>SVN(r.svc),fmt:r=>H(SVN(r.svc))},{k:"tot",label:"Lines, 24 h",val:r=>r.tot,fmt:r=>`<b class="num">${N0(r.tot)}</b>`},{k:"trend",label:"Trend",val:r=>r.trend,fmt:r=>`${spark(r.h,90,22,col(r.lvl==="ERROR"?"--bad-f":"--p4"))} <span class="small ${r.trend>2?"":"muted"}">${r.trend>2?"rising":"steady"}</span>`}],rows:()=>logRows(),open:id=>logDrawer(id)});
 return `<div class="statrow">${stat("Log patterns",rows.length,"templates found in 24 hours of lines")}${stat("Error patterns",errs.length,N0(sum(errs,r=>r.tot))+" error lines",errs.length?"crit":"")}${stat("New patterns today",rows.filter(r=>r.isNew).length,"never seen before")}${stat("Traces sampled",TRACES.length,TRACES.filter(t=>t.err).length+" with errors")}</div>
 ${card("Error clusters","Related error patterns grouped by likely cause. Each cluster links to the correlation group it explains.",`<div class="obs-clg">${cl.map(c=>{const ps=c.pat.map(i=>rows.find(r=>r.id==="LP"+(i+1))).filter(Boolean);return `<article class="obs-cov"><div class="row sp"><b>${H(c.n)}</b><span class="pill bad">${N0(sum(ps,p=>p.tot))} lines</span></div><p class="muted small">${H(c.txt)}</p><div class="row">${ps.map(p=>`<button class="chip" data-obs-log="${p.id}">${p.id}</button>`).join("")}${c.g?`<button class="chip" data-obs-grp="${c.g}">Group ${c.g}</button>`:""}</div></article>`}).join("")}</div>`)}
 ${card("Log patterns","The platform clusters raw lines into patterns so ten thousand lines read as a dozen rows. Search by text, service or level. Full text search and retention stay in Azure Log Analytics.",`<label class="obs-lf"><span>Filter patterns</span><input class="fin" type="search" value="${H(O.logQ||"")}" placeholder="Try: timeout, indexer, error" data-obs-logq></label>`+T)}
 ${card("Trace explorer","A trace follows one request through every service. Bars are spans drawn to scale. Red marks the span that dominates the time or fails.",`<div class="fchips" role="radiogroup" aria-label="Trace">${TRACES.map(t=>`<button class="chip" data-obs-trace="${t.id}" aria-pressed="${t.id===tr.id}">${H(t.op.slice(0,28))} · ${t.dur>=1000?P1(t.dur/1000)+" s":t.dur+" ms"}</button>`).join("")}</div><p class="story" data-role="story">${aiChip({model:"Event Correlator",conf:.84,title:"Trace insight",note:"Longest span on the critical path and its share of the total."})} ${H(tr.story)}</p>${waterfall(tr)}${legend([["Failed or dominant span","--bad-f"],["Portal","--p4"],["Standards Platform","--u3"],["Other services","--w1"]])}`)}`}
function logDrawer(id){const r=logRows().find(x=>x.id===id)||LOGP.map((p,i)=>({id:"LP"+(i+1),lvl:p[0],pat:p[1],svc:p[2],ci:p[3],h:[...Array(24)].map((_,k)=>logHour(p,k)),tot:0})).find(x=>x.id===id);if(!r)return;const smp=[...Array(5)].map((_,i)=>{const t=NOW_T-i*7-Math.floor(hn(id,i)*5);return hm(t)+":"+pad(Math.floor(hn(id,i+9)*60))+"  "+r.lvl+"  "+ciName(r.ci)+"  "+r.pat.replace("{ms}",N0(800+hn(id,i)*3000)).replace("{n}",N0(5000+hn(id,i)*12000)).replace("{user}","user"+(i+1)+"@meridian.example").replace("{ip}","10.4."+i+".1"+i).replace("{id}","PJ-"+(4100+i)).replace("{s}",P1(2+hn(id,i)*3))});
 openDrawer(`<div class="eyebrow">Log pattern ${r.id} · ${r.lvl}</div><h2 class="obs-h2 obs-mono">${H(r.pat)}</h2><div class="row obs-act"><span class="pill ${LVC[r.lvl]}">${r.lvl}</span>${svcLink(r.svc)}${ciLink(r.ci)}</div><div class="dfullgrid"><section class="card glass"><h3>Lines per hour, 24 hours</h3>${catBars([...Array(24)].map((_,i)=>hm(NOW_T-(23-i)*60).slice(0,2)),r.h,r.lvl==="ERROR"?"--bad-f":"--p4","lines")}</section><section class="card glass"><h3>Sample lines</h3><pre class="obs-pre">${H(smp.join("\n"))}</pre></section></div>`)}

/* ---------- forms: false positive, SLO, parameters, custom alert ---------- */
function fpForm(id){const a=computeAll().hist.find(x=>x.id===id)||computeAll().all.find(x=>x.id===id);if(!a)return;openForm({id:"obs_fpf",title:"Mark as false positive",story:"Tell the rules this alert was not worth a person's time. Marking one alert teaches the rule: after a few marks the event correlator will propose a suppression window or a better threshold, and you decide whether to accept it.",submit:"Mark false positive",
 fields:[{k:"kind",label:"Why",type:"chips",req:true,opts:["Expected behavior","Maintenance or test","Duplicate","Threshold too low","Vendor noise"]},{k:"why",label:"What happened",type:"longtext",ph:"For example: backup job warns every night and always passes on retry"},{k:"all",label:"Also mark earlier alerts from the same rule and CI",type:"toggle",help:"Teaches the suppression suggestion faster."}],defaults:{kind:"Expected behavior",all:true},
 live:v=>`<div class="story">${H(a.msg)} on ${H(ciName(a.ci))}. ${v.all?"Earlier alerts from this rule on this CI will also be marked.":""}</div>`,
 onSubmit:v=>{const m=O.fpMark;let n=0;const mark=x=>{m[x.rule+"|"+x.ci+"|"+x.fired]={why:v.why||v.kind,by:who_(),at:NOW_T,kind:v.kind};n++};mark(a);if(v.all)computeAll().hist.filter(x=>x.rule===a.rule&&x.ci===a.ci&&x.id!==a.id&&!x.fp).forEach(mark);bump();SGC=null;audit("marked false positive",a.id+" ("+n+" alerts) "+v.kind);render();return {toast:n+" alert"+(n>1?"s":"")+" marked. The event correlator will learn from this.",audit:a.id}}})}
function sloForm(){openForm({id:"obs_slof",title:"New SLO",story:"An SLO is a promise measured on what users feel: the share of 5-minute periods that were good. The error budget is what you may miss. Multi-window burn rate alerts warn you before it is spent.",submit:"Create SLO",fields:[{k:"n",label:"Name",type:"text",req:true,ph:"Editors can publish a standard"},{k:"svc",label:"Service",type:"select",req:true,opts:SVCREG.map(s=>[s.id,s.n])},{k:"ci",label:"Measured on",type:"select",req:true,opts:CIREG.map(c=>[c.id,c.name+" ("+c.class+")"])},{k:"m",label:"Good period means",type:"select",opts:["lat","err","avail","cpu","queue"].map(k=>[k,MET[k].n])},{k:"th",label:"Threshold",type:"number",req:true,help:"Latency in ms, error in %, availability in %, queue in messages."},{k:"tgt",label:"Objective (30 days)",type:"chips",opts:["99","99.5","99.9","99.95"]},{k:"own",label:"Owner",type:"people"}],defaults:{m:"lat",tgt:"99.5",th:2000,own:"Sam Patel",svc:"svc_portal",ci:"ci_por4"},
 live:v=>{const t=+v.tgt||99.5;return `<div class="story">${t}% over 30 days allows <b>${N0((1-t/100)*43200)} bad minutes</b> (${P1((1-t/100)*720)} hours) a month.</div>`},
 onSubmit:v=>{const s={id:"SL"+(O.slos.length+1),n:v.n,svc:v.svc,tgt:+v.tgt||99.5,sli:"Share of 5-minute periods with "+MET[v.m].n.toLowerCase()+(v.m==="avail"?" above ":" under ")+v.th+MET[v.m].u,own:v.own||"Sam Patel",good:[{ci:v.ci,m:v.m,op:v.m==="avail"?">":"<",th:+v.th}]};if(!metsOf(ciOf(v.ci)).includes(v.m))return {toast:"That CI does not report "+MET[v.m].n.toLowerCase()+". Pick another metric or CI.",close:false,audit:"validation"};O.slos.push(s);O.slo.sel=s.id;audit("created SLO",s.id+" "+s.n);render();return {toast:"SLO created with 30 days of history",audit:s.n}}})}
function paramForm(sc){openForm({id:"obs_par",title:"Add a parameter",story:"Parameters let one runbook serve many targets. The default is used unless the alert or the person running it supplies another value.",submit:"Add parameter",fields:[{k:"k",label:"Name",type:"text",req:true,ph:"vCores"},{k:"d",label:"Default value",type:"text",req:true}],onSubmit:v=>{draft(sc);sc.params.push({k:v.k,d:v.d});audit("edited runbook "+sc.id,"parameter "+v.k);render();return {toast:"Parameter added",audit:v.k}}})}
function pubForm(sc){openForm({id:"obs_pub",title:"Publish "+sc.id+" as a new version",story:"Publishing records who changed the runbook and why. Changes to the steps of a pre-approved standard change go back to the CAB for a light review, so the pre-approval stays valid.",submit:"Publish",fields:[{k:"note",label:"What changed",type:"text",req:true,ph:"Added the log check before restart"}],onSubmit:v=>{const n=(parseInt(String(sc.ver).replace(/\D/g,""),10)||1)+1;sc.ver="v"+n;sc.hist.unshift(["v"+n,TODAY,who_(),v.note]);delete O.draft[sc.id];audit("published runbook",sc.id+" v"+n+": "+v.note);render();return {toast:sc.id+" is now v"+n,audit:v.note}}})}
function injectForm(){openForm({id:"obs_inj",title:"Inject a custom alert",story:"Builds a sample alert and replays it through the automation rules. Nothing is created in the alert stream.",submit:"Replay",fields:[{k:"sev",label:"Severity",type:"chips",opts:[["1","Sev 1"],["2","Sev 2"],["3","Sev 3"],["4","Sev 4"]]},{k:"ci",label:"CI",type:"select",opts:CIREG.map(c=>[c.id,c.name])},{k:"m",label:"Metric",type:"select",opts:Object.keys(MET).map(k=>[k,MET[k].n]).concat([["event","Event"]])},{k:"msg",label:"Message",type:"text",ph:"Disk 91% used"}],defaults:{sev:"2",ci:"ci_sea0",m:"queue",msg:"Queue depth 18,000 messages"},
 onSubmit:v=>{const c=ciOf(v.ci),a={id:"CUSTOM",rule:"CUSTOM",ci:v.ci,svc:c.svc,m:v.m,sev:+v.sev,msg:v.msg||"Custom alert",lvl:"warn",count:1,flaps:0,active:true,from:NOW_T,fired:NOW_T,to:NOW_T,state:"Open",grp:"",k:"custom"};O.custom=a;O.simSel="CUSTOM";render();return {toast:"Replaying the custom alert",audit:a.msg}}})}

/* ---------- actions ---------- */
function ackAlert(id,silent){const a=computeAll().all.find(x=>x.id===id);if(!a)return;O.st[a.k]={st:"Acknowledged",by:who_(),at:NOW_T};bump();audit("acknowledged alert",id);if(!silent){toast("Acknowledged "+id,"good");render()}}
