document.addEventListener("pointermove",e=>{const w=e.target.closest&&e.target.closest("[data-obs-ch]");if(!w){return}const c=CH[w.dataset.obsCh];if(!c)return;const svg=w.querySelector("svg"),r=svg.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*c.W;const n=c.s[0].v.length,i=clamp(Math.round((x-c.L)/(c.W-c.L-c.R)*(n-1)),0,n-1),px=(c.L+(c.W-c.L-c.R)*i/Math.max(1,n-1))/c.W*100;const cur=svg.querySelector(".cur");cur.setAttribute("x1",c.L+(c.W-c.L-c.R)*i/Math.max(1,n-1));cur.setAttribute("x2",c.L+(c.W-c.L-c.R)*i/Math.max(1,n-1));cur.style.display="";const tip=w.querySelector(".obs-tip");tip.hidden=false;tip.innerHTML=`<b>${c.step>=60?fT(c.t0+i*c.step):hm(c.t0+i*c.step)}</b>`+c.s.map((s,k)=>`<span><i style="background:var(${s.c||["--p4","--u3","--w1","--e4","--s3","--p1"][k%6]})"></i>${H(s.l||"")} <b>${H(c.fmt(s.v[i]))}</b></span>`).join("");tip.style.left=Math.min(78,Math.max(2,px))+"%"});
