function evtScreen(){SYNCM();const A=computeAll(),op=A.day.filter(a=>a.active&&!a.sup&&!a.fp),top=A.groups.find(g=>g.active&&g.sev<=2);
 return `<div class="screen obs-screen">${hero("Event management",`${N0(A.fun[0])} signals in 24 hours, ${A.fun[4]} worth a person's time`,`Noise reduction is <b data-role="metric">${P1((1-A.fun[4]/Math.max(1,A.fun[0]))*100)}%</b>. ${top?`The biggest candidate, <b>${H(gTitle(top))}</b>, folds ${top.n} alerts into one group: ${H(top.reason)}.`:"No Sev 1 or 2 group is active."} MTTD is <b data-role="metric">${P1(A.mttd)} min</b> and MTTA <b data-role="metric">${P1(A.mtta)} min</b>.`,`<div class="row">${fchip("m_noise")}${fchip("m_mttd")}${fchip("m_mtta")}${fchip("m_fprate")}${fchip("m_fatigue")}${stdChip("itil5","Event management practice: detect, filter, correlate, then trigger the right response")}${stdChip("sre","Alert on symptoms users feel; page only for what needs a human")}</div>`)}${lensNote()}
 ${views("obs_evt",["NOC wall","Alert stream","Correlation and noise","Patterns","False positives","Thresholds and windows"],[wallPane(),streamPane(),corrPane(),patPane(),fpPane(),thrPane()])}${procCard("itom_evt")}</div>`}
